CREATE TABLE IF NOT EXISTS robot_health_snapshot (
    robot_id TEXT PRIMARY KEY,
    snapshot_date DATE,
    initial_condition_index REAL
);

INSERT INTO robot_health_snapshot (robot_id, snapshot_date, initial_condition_index)
SELECT r.botdetreg, r.instdateval, p.conditionindexval
FROM robot_details r
JOIN performance_and_safety p ON r.botdetreg = p.effectivenessrobot
WHERE r.instdateval >= (SELECT MAX(instdateval) FROM robot_details) - INTERVAL '30 days';

ALTER TABLE robot_details ALTER COLUMN instdateval SET NOT NULL;
